"use client";

import { startTransition, useEffect, useState } from "react";
import { apiRequest } from "@/compartido/lib/api";
import type { AdminConsolePayload } from "@/compartido/types/admin";

type AdminConsoleQuery = {
  activityType?: string;
  activityLimit?: number;
  from?: string;
  to?: string;
};

export function useAdminConsole(enabled: boolean, refreshIntervalMs = 0, query?: AdminConsoleQuery) {
  const [consoleData, setConsoleData] = useState<AdminConsolePayload | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [lastUpdatedAt, setLastUpdatedAt] = useState<string | null>(null);
  const [refreshTick, setRefreshTick] = useState(0);

  useEffect(() => {
    let cancelled = false;

    const params = new URLSearchParams();
    if (query?.activityType) {
      params.set("activityType", query.activityType);
    }
    if (typeof query?.activityLimit === "number") {
      params.set("activityLimit", String(query.activityLimit));
    }
    if (query?.from) {
      params.set("from", query.from);
    }
    if (query?.to) {
      params.set("to", query.to);
    }
    const requestUrl = params.size > 0 ? `/api/admin/console?${params.toString()}` : "/api/admin/console";

    const run = async () => {
      if (!enabled) {
        startTransition(() => setConsoleData(null));
        setLastUpdatedAt(null);
        return;
      }

      setIsLoading(true);
      const response = await apiRequest<AdminConsolePayload>(requestUrl);
      if (!cancelled && response.ok && response.data) {
        startTransition(() => setConsoleData(response.data));
        setLastUpdatedAt(new Date().toISOString());
      }
      if (!cancelled) {
        setIsLoading(false);
      }
    };

    void run();
    const intervalId =
      enabled && refreshIntervalMs > 0
        ? window.setInterval(() => {
            void run();
          }, refreshIntervalMs)
        : null;

    return () => {
      cancelled = true;
      if (intervalId) {
        window.clearInterval(intervalId);
      }
    };
  }, [enabled, query?.activityLimit, query?.activityType, query?.from, query?.to, refreshIntervalMs, refreshTick]);

  return {
    consoleData,
    isLoading,
    lastUpdatedAt,
    refreshConsole: () => setRefreshTick((current) => current + 1),
  };
}
