"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useEffect, useRef, useState } from "react";
import {
  Bell,
  BriefcaseBusiness,
  ChevronUp,
  Languages,
  LayoutDashboard,
  ListTodo,
  MessageSquareMore,
  Moon,
  Plus,
  Search,
  Settings,
  Siren,
  Sun,
  Users,
} from "lucide-react";
import { InlineConfirm } from "@/compartido/components/ui/inline-confirm";
import { useAppLanguage } from "@/compartido/hooks/use-app-language";
import { useAuthUser } from "@/compartido/hooks/use-auth-user";
import { useAdminConsole } from "@/frontend/admin/hooks/use-admin-console";
import {
  adminMutedClass,
  adminSurfaceClass,
  adminTitleClass,
  AdminPill,
} from "@/frontend/admin/components/system/admin-dashboard-kit";

type ShellProps = {
  isDark: boolean;
  onToggleTheme: () => void;
  title: string;
  description?: string;
  actions?: React.ReactNode;
  children: React.ReactNode;
};

type NavItem = {
  label: string;
  href: string;
  icon: typeof LayoutDashboard;
  badge?: string;
};

const NAV_GROUPS: Array<{ title: string; items: NavItem[] }> = [
  {
    title: "General",
    items: [
      { label: "Dashboard", href: "/admin", icon: LayoutDashboard },
      { label: "Tasks", href: "/admin/tasks", icon: ListTodo },
      { label: "Crear/Create", href: "/admin/create", icon: Plus },
      { label: "Chats", href: "/admin/chats", icon: MessageSquareMore },
      { label: "Users", href: "/admin/usuarios", icon: Users },
      { label: "Empresas", href: "/admin/vacantes", icon: BriefcaseBusiness },
    ],
  },
  {
    title: "Pages",
    items: [
      { label: "Errors", href: "/admin/errors", icon: Siren },
      { label: "Papelera", href: "/admin/usuarios#papelera", icon: Users },
    ],
  },
  {
    title: "Other",
    items: [
      { label: "Settings", href: "/admin/settings", icon: Settings },
    ],
  },
];

function joinClasses(...values: Array<string | false | null | undefined>) {
  return values.filter(Boolean).join(" ");
}

function isActive(pathname: string, href: string) {
  return pathname === href;
}

export function AdminDashboardShell({ isDark, onToggleTheme, title, description, actions, children }: ShellProps) {
  const pathname = usePathname();
  const { language, setLanguage } = useAppLanguage();
  const { authUser, signOut } = useAuthUser();
  const { consoleData } = useAdminConsole(authUser?.role === "admin", 60_000);
  const adminName = authUser?.nombre?.trim() || "Mike Morron";
  const [adminMenuOpen, setAdminMenuOpen] = useState(false);
  const [logoutConfirmOpen, setLogoutConfirmOpen] = useState(false);
  const adminMenuRef = useRef<HTMLDivElement | null>(null);
  const navGroups = NAV_GROUPS.map((group) => ({
    ...group,
    items: group.items.map((item) => ({
      ...item,
      badge:
        item.href === "/admin/chats"
          ? String(consoleData?.metrics.reportedChatsTotal ?? 0)
          : item.href === "/admin/tasks"
            ? String((consoleData?.activities ?? []).filter((activity) => activity.type === "api_request").length ?? 0)
            : item.badge,
    })),
  }));

  useEffect(() => {
    if (!adminMenuOpen) {
      return;
    }

    const handlePointerDown = (event: PointerEvent) => {
      const target = event.target as Node | null;
      if (adminMenuRef.current?.contains(target ?? null)) {
        return;
      }

      setAdminMenuOpen(false);
      setLogoutConfirmOpen(false);
    };

    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setAdminMenuOpen(false);
        setLogoutConfirmOpen(false);
      }
    };

    window.addEventListener("pointerdown", handlePointerDown);
    window.addEventListener("keydown", handleEscape);
    return () => {
      window.removeEventListener("pointerdown", handlePointerDown);
      window.removeEventListener("keydown", handleEscape);
    };
  }, [adminMenuOpen]);

  return (
    <main className={isDark ? "min-h-screen bg-[#0b1020] text-slate-100" : "min-h-screen bg-[#f6f8fb] text-slate-900"}>
      <div className="grid min-h-screen xl:grid-cols-[250px_minmax(0,1fr)]">
        <aside className={isDark ? "sticky top-0 h-screen overflow-y-auto border-r border-white/8 bg-[#0a0f1d]" : "sticky top-0 h-screen overflow-y-auto border-r border-slate-200 bg-white"}>
          <div className="flex min-h-full flex-col px-4 py-4">
            <div className="mt-5 flex-1 space-y-7">
              {navGroups.map((group) => (
                <div key={group.title}>
                  <p className={isDark ? "px-2 text-[11px] font-semibold uppercase tracking-[0.22em] text-slate-500" : "px-2 text-[11px] font-semibold uppercase tracking-[0.22em] text-slate-400"}>
                    {group.title}
                  </p>
                  <div className="mt-2.5 space-y-1">
                    {group.items.map((item) => {
                      const active = isActive(pathname, item.href);

                      return (
                        <Link
                          key={item.href}
                          href={item.href}
                          className={
                            active
                              ? isDark
                                ? "flex items-center justify-between rounded-2xl border border-white/10 bg-white/8 px-3 py-2.5 text-sm font-medium text-white"
                                : "flex items-center justify-between rounded-2xl border border-slate-200 bg-slate-100 px-3 py-2.5 text-sm font-medium text-slate-950"
                              : isDark
                                ? "flex items-center justify-between rounded-2xl px-3 py-2.5 text-sm text-slate-300 transition hover:bg-white/5 hover:text-white"
                                : "flex items-center justify-between rounded-2xl px-3 py-2.5 text-sm text-slate-700 transition hover:bg-slate-100 hover:text-slate-950"
                          }
                        >
                          <span className="inline-flex items-center gap-2.5">
                            <item.icon className="h-4 w-4" />
                            {item.label}
                          </span>
                          {item.badge && item.badge !== "0" ? <AdminPill isDark={isDark}>{item.badge}</AdminPill> : null}
                        </Link>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>

            <div className="relative mt-6" ref={adminMenuRef}>
              {adminMenuOpen ? (
                <div className={isDark ? "absolute inset-x-0 bottom-[calc(100%+0.65rem)] rounded-2xl border border-white/8 bg-[#0c1328] p-3 shadow-[0_20px_50px_rgba(0,0,0,0.34)]" : "absolute inset-x-0 bottom-[calc(100%+0.65rem)] rounded-2xl border border-slate-200 bg-white p-3 shadow-[0_20px_50px_rgba(148,163,184,0.24)]"}>
                  {logoutConfirmOpen ? (
                    <InlineConfirm
                      message="Cerrar sesion?"
                      confirmLabel="Si"
                      cancelLabel="No"
                      onConfirm={() => {
                        setAdminMenuOpen(false);
                        setLogoutConfirmOpen(false);
                        void signOut();
                      }}
                      onCancel={() => setLogoutConfirmOpen(false)}
                      className={isDark ? "text-slate-100" : "text-slate-900"}
                      confirmClassName="rounded-full bg-red-600 px-3 py-1.5 text-xs font-semibold text-white transition duration-300 hover:bg-red-700"
                      cancelClassName={isDark ? "rounded-full border border-white/10 bg-white/6 px-3 py-1.5 text-xs font-semibold text-slate-100 transition duration-300 hover:bg-white/10" : "rounded-full border border-slate-300 bg-slate-50 px-3 py-1.5 text-xs font-semibold text-slate-700 transition duration-300 hover:bg-slate-100"}
                    />
                  ) : (
                    <button
                      type="button"
                      onClick={() => setLogoutConfirmOpen(true)}
                      className={isDark ? "flex w-full items-center justify-between rounded-xl px-3 py-2.5 text-sm text-slate-200 transition hover:bg-white/6 hover:text-white" : "flex w-full items-center justify-between rounded-xl px-3 py-2.5 text-sm text-slate-700 transition hover:bg-slate-100 hover:text-slate-950"}
                    >
                      <span>Cerrar sesion</span>
                      <ChevronUp className="h-4 w-4 rotate-180" />
                    </button>
                  )}
                </div>
              ) : null}

              <button
                type="button"
                onClick={() => {
                  setLogoutConfirmOpen(false);
                  setAdminMenuOpen((current) => !current);
                }}
                className={adminSurfaceClass(isDark, "w-full p-3 text-left hover:translate-y-[-1px]")}
                aria-expanded={adminMenuOpen}
                aria-label="Menu del administrador"
              >
                <div className="flex items-center justify-between gap-3">
                  <div>
                    <p className={joinClasses("text-sm font-semibold", adminTitleClass(isDark))}>
                      {adminName}
                    </p>
                    <p className={joinClasses("mt-1 text-xs leading-5", adminMutedClass(isDark))}>
                      Administrador
                    </p>
                  </div>
                  <ChevronUp className={`h-4 w-4 transition ${adminMenuOpen ? "rotate-0" : "rotate-180"} ${isDark ? "text-slate-300" : "text-slate-600"}`} />
                </div>
              </button>
            </div>
          </div>
        </aside>

        <section className="min-w-0">
          <header className={isDark ? "sticky top-0 z-20 border-b border-white/8 bg-[#0b1020]/92 backdrop-blur" : "sticky top-0 z-20 border-b border-slate-200 bg-white/92 backdrop-blur"}>
            <div className="flex items-center gap-3 px-5 py-4">
              <button
                type="button"
                className={isDark ? "inline-flex h-10 w-10 items-center justify-center rounded-2xl border border-white/10 bg-white/5 text-slate-200" : "inline-flex h-10 w-10 items-center justify-center rounded-2xl border border-slate-200 bg-slate-50 text-slate-700"}
              >
                <LayoutDashboard className="h-4 w-4" />
              </button>
              <div className={isDark ? "relative max-w-md flex-1 rounded-2xl border border-white/10 bg-white/5" : "relative max-w-md flex-1 rounded-2xl border border-slate-200 bg-slate-50"}>
                <Search className={isDark ? "pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" : "pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500"} />
                <input
                  readOnly
                  value=""
                  placeholder="Search admin modules"
                  className={isDark ? "h-11 w-full bg-transparent pl-10 pr-12 text-sm text-white outline-none placeholder:text-slate-400" : "h-11 w-full bg-transparent pl-10 pr-12 text-sm text-slate-900 outline-none placeholder:text-slate-500"}
                />
                <span className={isDark ? "absolute right-3 top-1/2 -translate-y-1/2 rounded-md border border-white/10 bg-white/4 px-1.5 py-0.5 text-[10px] text-slate-400" : "absolute right-3 top-1/2 -translate-y-1/2 rounded-md border border-slate-200 bg-white px-1.5 py-0.5 text-[10px] text-slate-500"}>
                  ⌘ K
                </span>
              </div>

              <div className="ml-auto flex items-center gap-3">
                <button
                  type="button"
                  onClick={() => void setLanguage(language === "es" ? "en" : "es")}
                  className={isDark ? "inline-flex h-10 items-center justify-center gap-2 rounded-2xl border border-white/10 bg-white/5 px-3 text-slate-200" : "inline-flex h-10 items-center justify-center gap-2 rounded-2xl border border-slate-200 bg-slate-50 px-3 text-slate-700"}
                  aria-label="Cambiar idioma"
                >
                  <Languages className="h-4 w-4" />
                  <span className="text-xs font-medium uppercase">{language}</span>
                </button>
                <button
                  type="button"
                  onClick={onToggleTheme}
                  className={isDark ? "inline-flex h-10 w-10 items-center justify-center rounded-2xl border border-white/10 bg-white/5 text-slate-200" : "inline-flex h-10 w-10 items-center justify-center rounded-2xl border border-slate-200 bg-slate-50 text-slate-700"}
                  aria-label="Cambiar tema"
                >
                  {isDark ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}
                </button>
                <button
                  type="button"
                  className={isDark ? "inline-flex h-10 w-10 items-center justify-center rounded-2xl border border-white/10 bg-white/5 text-slate-200" : "inline-flex h-10 w-10 items-center justify-center rounded-2xl border border-slate-200 bg-slate-50 text-slate-700"}
                  aria-label="Notifications"
                >
                  <Bell className="h-4 w-4" />
                </button>
                <div className="flex items-center gap-3">{actions}</div>
              </div>
            </div>
          </header>

          <div className="p-5 xl:p-8">
            <section className={adminSurfaceClass(isDark, "p-6")}>
              <p className={joinClasses("text-[11px] font-semibold uppercase tracking-[0.24em]", adminMutedClass(isDark))}>
                Admin / {title}
              </p>
              <h1 className={joinClasses("mt-3 text-3xl font-semibold tracking-tight", adminTitleClass(isDark))}>
                {title}
              </h1>
              {description ? (
                <p className={joinClasses("mt-3 max-w-3xl text-sm leading-7", adminMutedClass(isDark))}>
                  {description}
                </p>
              ) : null}
            </section>

            <div className="mt-5 space-y-5">{children}</div>
          </div>
        </section>
      </div>
    </main>
  );
}
