"use client";

import type { LucideIcon } from "lucide-react";

function joinClasses(...values: Array<string | false | null | undefined>) {
  return values.filter(Boolean).join(" ");
}

export function adminSurfaceClass(isDark: boolean, className?: string) {
  return joinClasses(
    "rounded-3xl border p-5 shadow-sm transition",
    isDark
      ? "border-white/10 bg-[linear-gradient(180deg,rgba(20,25,39,0.96),rgba(13,18,30,0.94))] shadow-[0_18px_42px_rgba(0,0,0,0.24)]"
      : "border-slate-200 bg-white shadow-[0_18px_40px_rgba(148,163,184,0.10)]",
    className,
  );
}

export function adminMutedClass(isDark: boolean) {
  return isDark ? "text-slate-400" : "text-slate-500";
}

export function adminTitleClass(isDark: boolean) {
  return isDark ? "text-slate-50" : "text-slate-950";
}

export function AdminSurface({
  isDark,
  className,
  id,
  children,
}: {
  isDark: boolean;
  className?: string;
  id?: string;
  children: React.ReactNode;
}) {
  return <section id={id} className={adminSurfaceClass(isDark, className)}>{children}</section>;
}

export function AdminSectionHeading({
  isDark,
  eyebrow,
  title,
  description,
  action,
}: {
  isDark: boolean;
  eyebrow?: string;
  title: string;
  description?: string;
  action?: React.ReactNode;
}) {
  return (
    <div className="flex flex-wrap items-start justify-between gap-4">
      <div>
        {eyebrow ? (
          <p className={joinClasses("text-[11px] font-semibold uppercase tracking-[0.22em]", adminMutedClass(isDark))}>
            {eyebrow}
          </p>
        ) : null}
        <h2 className={joinClasses("text-xl font-semibold tracking-tight", adminTitleClass(isDark), eyebrow ? "mt-2" : "")}>
          {title}
        </h2>
        {description ? (
          <p className={joinClasses("mt-2 text-sm leading-6", adminMutedClass(isDark))}>
            {description}
          </p>
        ) : null}
      </div>
      {action}
    </div>
  );
}

export function AdminStatCard({
  isDark,
  icon: Icon,
  label,
  value,
  helper,
}: {
  isDark: boolean;
  icon: LucideIcon;
  label: string;
  value: string | number;
  helper?: string;
}) {
  return (
    <AdminSurface isDark={isDark}>
      <div className="flex items-center justify-between gap-3">
        <p className={joinClasses("text-[11px] font-semibold uppercase tracking-[0.22em]", adminMutedClass(isDark))}>
          {label}
        </p>
        <span
          className={joinClasses(
            "inline-flex h-10 w-10 items-center justify-center rounded-2xl border",
            isDark ? "border-white/10 bg-white/5 text-slate-200" : "border-slate-200 bg-slate-50 text-slate-700",
          )}
        >
          <Icon className="h-4 w-4" />
        </span>
      </div>
      <div className="mt-4">
        <p className={joinClasses("text-3xl font-semibold tracking-tight", adminTitleClass(isDark))}>
          {value}
        </p>
        {helper ? <p className={joinClasses("mt-2 text-sm", adminMutedClass(isDark))}>{helper}</p> : null}
      </div>
    </AdminSurface>
  );
}

export function AdminPill({
  isDark,
  children,
  tone = "neutral",
}: {
  isDark: boolean;
  children: React.ReactNode;
  tone?: "neutral" | "success" | "warning" | "danger";
}) {
  const toneClass =
    tone === "success"
      ? isDark
        ? "border-emerald-400/20 bg-emerald-500/10 text-emerald-100"
        : "border-emerald-200 bg-emerald-50 text-emerald-700"
      : tone === "warning"
        ? isDark
          ? "border-amber-400/20 bg-amber-500/10 text-amber-100"
          : "border-amber-200 bg-amber-50 text-amber-700"
        : tone === "danger"
          ? isDark
            ? "border-rose-400/20 bg-rose-500/10 text-rose-100"
            : "border-rose-200 bg-rose-50 text-rose-700"
          : isDark
            ? "border-white/10 bg-white/5 text-slate-200"
            : "border-slate-200 bg-slate-50 text-slate-700";

  return (
    <span className={joinClasses("inline-flex items-center rounded-full border px-2.5 py-1 text-[11px] font-medium", toneClass)}>
      {children}
    </span>
  );
}

export function AdminToolbarInput({
  isDark,
  value,
  onChange,
  placeholder,
  className,
}: {
  isDark: boolean;
  value: string;
  onChange: React.ChangeEventHandler<HTMLInputElement>;
  placeholder: string;
  className?: string;
}) {
  return (
    <input
      value={value}
      onChange={onChange}
      placeholder={placeholder}
      className={joinClasses(
        "h-11 rounded-2xl border px-4 text-sm outline-none transition",
        isDark
          ? "border-white/10 bg-white/5 text-white placeholder:text-slate-500"
          : "border-slate-200 bg-white text-slate-900 placeholder:text-slate-400",
        className,
      )}
    />
  );
}

export function AdminToolbarSelect({
  isDark,
  value,
  onChange,
  children,
  className,
}: {
  isDark: boolean;
  value: string;
  onChange: React.ChangeEventHandler<HTMLSelectElement>;
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <select
      value={value}
      onChange={onChange}
      className={joinClasses(
        "h-11 rounded-2xl border px-4 text-sm outline-none transition",
        isDark ? "border-white/10 bg-white/5 text-white" : "border-slate-200 bg-white text-slate-900",
        className,
      )}
    >
      {children}
    </select>
  );
}

export function AdminGhostButton({
  isDark,
  children,
  className,
  ...props
}: React.ButtonHTMLAttributes<HTMLButtonElement> & {
  isDark: boolean;
}) {
  return (
    <button
      {...props}
      className={joinClasses(
        "inline-flex items-center gap-2 rounded-2xl border px-4 py-2.5 text-sm font-medium transition",
        isDark
          ? "border-white/10 bg-white/5 text-slate-100 hover:bg-white/8"
          : "border-slate-200 bg-white text-slate-700 hover:bg-slate-50",
        className,
      )}
    >
      {children}
    </button>
  );
}

export function AdminPrimaryButton({
  children,
  className,
  ...props
}: React.ButtonHTMLAttributes<HTMLButtonElement>) {
  return (
    <button
      {...props}
      className={joinClasses(
        "inline-flex items-center gap-2 rounded-2xl bg-slate-950 px-4 py-2.5 text-sm font-medium text-white transition hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-70",
        className,
      )}
    >
      {children}
    </button>
  );
}

export function AdminSimpleTable({
  isDark,
  children,
}: {
  isDark: boolean;
  children: React.ReactNode;
}) {
  return (
    <div className={joinClasses("overflow-hidden rounded-3xl border", isDark ? "border-white/10 bg-[#0f1523]" : "border-slate-200 bg-white")}>
      <div className="overflow-x-auto">{children}</div>
    </div>
  );
}
